const int MAX_SIZE = 200010;
const int MAX_LIMIT = 1000010;

vector<ll> pattern_numbers({0ll});
int min_moves = MAX_LIMIT;

void search(ll x, int steps) {
    if (steps > min_moves)
        return;
    if (x == 0) {
        min_moves = steps;
        return;
    }
    auto lower_it = lower_bound(all(pattern_numbers), x);
    auto upper_it = upper_bound(all(pattern_numbers), x);
    if (lower_it == upper_it) lower_it--;
    ll diff_a = x - *lower_it;
    int cost = lower_it - pattern_numbers.begin();
    ll diff_b = *upper_it - x;
    search(x % *lower_it, steps + cost * (x / *lower_it));
    search(diff_b, steps + cost + 1);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    ll n;
    cin >> n;
    for (int i = 1; i <= 16; ++i) {
        pattern_numbers.push_back(pattern_numbers.back() * 10 + 1);
